/**
 * The sticker catalog and sticker glyph rules.
 *
 * Two open sets:
 * - **Emoji** (`STICKER_EMOJI`): named emoji, keyed by a plain word
 *   (`lightbulb`, `thumbs-up`…). Drawn with the system emoji font.
 * - **Icons** (`ICON_STICKERS`): lucide icons drawn in a marker look, keyed
 *   `icon-<lucide name>`. Each has an emoji fallback glyph for screen readers,
 *   text exports and readers that do not know the key.
 *
 * Plus the face sticker (`art: "face"`): the placer's avatar, which counts
 * as a vote. Any single emoji also works as a sticker without `art`.
 */

import { FACE_STICKER_ART } from './schema.ts';

