/** One icon sticker: a lucide icon with a label and an emoji fallback. */
export interface IconSticker {
  /** The `art` key: `icon-<icon>`. */
  key: `icon-${string}`;
  /** The lucide icon name (kebab case). */
  icon: string;
  label: string;
  /** Emoji shown where the icon cannot be drawn. */
  glyph: string;
}

