/** Icon stickers, in picker order. */
export const ICON_STICKERS: readonly IconSticker[] = ICON_STICKER_ROWS.map(([icon, label, glyph]) => ({ key: `icon-${icon}`, icon, label, glyph }));

/** A group of the picker: icon stickers (lucide names) and emoji stickers (keys) on one theme. */
export interface StickerCategory {
  id: string;
  label: string;
  /** Lucide names of its icon stickers (`icon-<name>`), in picker order. */
  icons: readonly string[];
  /** Keys of its emoji stickers, in picker order. */
  emoji: readonly string[];
}

