const ICON_STICKER_BY_KEY: ReadonlyMap<string, IconSticker> = new Map(ICON_STICKERS.map((sticker) => [sticker.key, sticker]));

/** The icon sticker of an `art` key. */
export function iconStickerOf(art: string | undefined): IconSticker | undefined {
  return art === undefined ? undefined : ICON_STICKER_BY_KEY.get(art);
}

/** True for a named emoji key. */
export function isEmojiStickerArt(art: unknown): art is string {
  return typeof art === 'string' && Object.hasOwn(STICKER_EMOJI, art);
}

/** True for any catalog key (emoji, icon) or the face sticker. */
export function isStickerArt(art: unknown): art is string {
  return art === FACE_STICKER_ART || isEmojiStickerArt(art) || (typeof art === 'string' && ICON_STICKER_BY_KEY.has(art));
}

/** The fallback emoji of a catalog key. */
export function stickerGlyphForArt(art: string): string | undefined {
  return isEmojiStickerArt(art) ? STICKER_EMOJI[art] : ICON_STICKER_BY_KEY.get(art)?.glyph;
}

/** A readable name of a sticker. */
export function stickerLabel(sticker: { art?: string; glyph: string }): string {
  if (sticker.art === FACE_STICKER_ART) return 'Vote';
  const icon = iconStickerOf(sticker.art);
  if (icon !== undefined) return icon.label;
  return sticker.art !== undefined && isEmojiStickerArt(sticker.art) ? sticker.art.replaceAll('-', ' ') : sticker.glyph;
}

/** Emoji → its first named key (variation selectors ignored). */
export const STICKER_ART_BY_EMOJI: ReadonlyMap<string, string> = (() => {
  const map = new Map<string, string>();
  for (const [key, glyph] of Object.entries(STICKER_EMOJI)) {
    const bare = glyph.replace(/️/g, '');
    if (!map.has(bare)) map.set(bare, key);
  }
  return map;
})();

/** The named key of an emoji, when the catalog has it. */
export function stickerArtForEmoji(glyph: string): string | undefined {
  return STICKER_ART_BY_EMOJI.get(glyph.replace(/️/g, ''));
}

/**
 * A sticker glyph: one emoji grapheme (keycaps allowed), at most 8 code
 * points; plain text, lone modifiers and several graphemes are refused.
 */
export function normalizeStickerGlyph(glyph: unknown): string | undefined {
  if (typeof glyph !== 'string') return undefined;
  const trimmed = glyph.trim();
  const chars = [...trimmed];
  if (chars.length === 0 || chars.length > 8) return undefined;
  if (!/^[0-9#*]️?⃣$/u.test(trimmed) && chars.some((char) => (char.codePointAt(0) ?? 0) < 0x200d)) return undefined;
  const modifierPattern = /^(?:\p{Cf}|[︀-️⃣\u{1f3fb}-\u{1f3ff}])$/u;
  if (chars.every((char) => modifierPattern.test(char))) return undefined;
  if (typeof Intl.Segmenter === 'function' && [...new Intl.Segmenter('en', { granularity: 'grapheme' }).segment(trimmed)].length !== 1) return undefined;
  return trimmed;
}
